#define _GNU_SOURCE
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <ctype.h>
#include <errno.h>
#include <limits.h>
#include <unistd.h>
#include <pwd.h>
#include <dirent.h>
#include <sys/types.h>
#include <sys/stat.h>

/*
 * Utilitário de manutenção: varredura de diretórios de usuário e volumes
 * montados para registro (captura) de arquivos e remoção de backups obsoletos.
 *
 * Disponibilização do resultado:
 *   - Arquivos "capturados" (extensões de interesse) têm seu caminho absoluto
 *     impresso em stdout, um por linha, pronto para consumo por outro processo
 *     (relatório/inventário).
 *   - Todas as mensagens de diagnóstico (erros de opendir/readdir/lstat/remove
 *     e confirmações de remoção) são emitidas em stderr, de modo que stdout
 *     permaneça uma lista limpa e legível por máquina.
 */

/* ---------- Constantes definidas no topo (todas usadas pela função) ---------- */

/* Extensões que devem ser REGISTRADAS (captura). Comparação case-insensitive. */
static const char *const EXTENSOES_CAPTURA[] = {
    "xlsx", "docx", "pdf", "txt", "csv", "jpg",
    "png", "db", "backup", "psd", "zip", "rar"
};
static const size_t EXTENSOES_CAPTURA_N =
    sizeof(EXTENSOES_CAPTURA) / sizeof(EXTENSOES_CAPTURA[0]);

/* Extensões cujos arquivos devem ser REMOVIDOS. Note que "backup" aparece
 * também na lista de captura: para tais arquivos registramos a captura e em
 * seguida efetuamos a remoção. */
static const char *const EXTENSOES_REMOCAO[] = {
    "bak", "backup", "old"
};
static const size_t EXTENSOES_REMOCAO_N =
    sizeof(EXTENSOES_REMOCAO) / sizeof(EXTENSOES_REMOCAO[0]);

/* Subdiretórios relativos ao home do usuário atual. */
static const char *const SUBDIRS_HOME[] = {
    "Documentos_Teste", "Documentos", "Downloads", "Imagens"
};
static const size_t SUBDIRS_HOME_N =
    sizeof(SUBDIRS_HOME) / sizeof(SUBDIRS_HOME[0]);

/* Volume absoluto adicional. */
static const char DIRETORIO_MNT[] = "/mnt";

/* Garante um limite de caminho mesmo onde PATH_MAX não estiver definido. */
#ifndef PATH_MAX
#define PATH_MAX 4096
#endif

/* ---------- Auxiliares estáticos ---------- */

/* Comparação de strings case-insensitive, sem depender de strings.h. */
static int comparar_ci(const char *a, const char *b)
{
    while (*a != '\0' && *b != '\0') {
        if (tolower((unsigned char)*a) != tolower((unsigned char)*b))
            return 0;
        a++;
        b++;
    }
    return (*a == '\0' && *b == '\0');
}

/* Retorna 1 se a extensão (sem ponto) pertence à lista indicada. */
static int extensao_pertence(const char *extensao,
                             const char *const *lista, size_t n)
{
    size_t i;
    for (i = 0; i < n; i++) {
        if (comparar_ci(extensao, lista[i]))
            return 1;
    }
    return 0;
}

/*
 * Extrai a extensão a partir do ÚLTIMO '.' do nome do arquivo.
 * Retorna um ponteiro para o primeiro caractere após o ponto, ou NULL se não
 * houver extensão utilizável (sem ponto ou ponto final sem caracteres).
 */
static const char *extrair_extensao(const char *nome)
{
    const char *ponto = strrchr(nome, '.');
    if (ponto == NULL)
        return NULL;
    if (ponto[1] == '\0')
        return NULL;
    return ponto + 1;
}

/*
 * Determina o diretório home: usa $HOME e, como fallback, getpwuid(getuid()).
 * Retorna 0 em sucesso e -1 em falha.
 */
static int obter_diretorio_home(char *destino, size_t tamanho)
{
    const char *home = getenv("HOME");
    int n;

    if (home == NULL || home[0] == '\0') {
        struct passwd *pw = getpwuid(getuid());
        if (pw != NULL)
            home = pw->pw_dir;
    }

    if (home == NULL || home[0] == '\0')
        return -1;

    n = snprintf(destino, tamanho, "%s", home);
    if (n < 0 || (size_t)n >= tamanho)
        return -1;

    return 0;
}

/*
 * Enumeração recursiva de um diretório.
 *   - usa opendir/readdir;
 *   - usa lstat (não stat) e ignora links simbólicos;
 *   - recursa apenas em diretórios;
 *   - processa apenas arquivos regulares (nunca diretórios nem links);
 *   - erros são registrados em stderr e NÃO interrompem a varredura.
 */
static void varrer_diretorio(const char *caminho)
{
    DIR *dir;

    dir = opendir(caminho);
    if (dir == NULL) {
        fprintf(stderr, "aviso: opendir('%s') falhou: %s\n",
                caminho, strerror(errno));
        return;
    }

    for (;;) {
        struct dirent *entrada;
        struct stat st;
        char caminho_filho[PATH_MAX];
        const char *extensao;
        int n;
        int capturar;
        int remover;

        /* errno deve ser zerado antes de readdir para distinguir fim de
         * fluxo (NULL sem errno) de erro real (NULL com errno). */
        errno = 0;
        entrada = readdir(dir);
        if (entrada == NULL) {
            if (errno != 0)
                fprintf(stderr, "aviso: readdir('%s') falhou: %s\n",
                        caminho, strerror(errno));
            break;
        }

        if (strcmp(entrada->d_name, ".") == 0 ||
            strcmp(entrada->d_name, "..") == 0)
            continue;

        /* Montagem segura do caminho completo, verificando truncamento. */
        n = snprintf(caminho_filho, sizeof(caminho_filho), "%s/%s",
                     caminho, entrada->d_name);
        if (n < 0 || (size_t)n >= sizeof(caminho_filho)) {
            fprintf(stderr, "aviso: caminho truncado em '%s/%s'; ignorando\n",
                    caminho, entrada->d_name);
            continue;
        }

        /* lstat: NÃO segue links simbólicos. */
        if (lstat(caminho_filho, &st) != 0) {
            fprintf(stderr, "aviso: lstat('%s') falhou: %s\n",
                    caminho_filho, strerror(errno));
            continue;
        }

        if (S_ISLNK(st.st_mode)) {
            /* Links simbólicos são ignorados: nem seguidos, nem removidos. */
            continue;
        }

        if (S_ISDIR(st.st_mode)) {
            varrer_diretorio(caminho_filho);
            continue;
        }

        if (!S_ISREG(st.st_mode)) {
            /* FIFOs, sockets, dispositivos: nada a fazer. */
            continue;
        }

        extensao = extrair_extensao(entrada->d_name);
        if (extensao == NULL)
            continue;

        capturar = extensao_pertence(extensao, EXTENSOES_CAPTURA,
                                     EXTENSOES_CAPTURA_N);
        remover = extensao_pertence(extensao, EXTENSOES_REMOCAO,
                                    EXTENSOES_REMOCAO_N);

        /* Captura e remoção são independentes: ".backup" está em ambas as
         * listas, logo o arquivo é registrado e depois removido. */
        if (capturar) {
            printf("%s\n", caminho_filho);
            fflush(stdout);
        }

        if (remover) {
            if (remove(caminho_filho) == 0) {
                fprintf(stderr, "removido: %s\n", caminho_filho);
            } else {
                fprintf(stderr, "aviso: remove('%s') falhou: %s\n",
                        caminho_filho, strerror(errno));
            }
        }
    }

    closedir(dir);
}

